package org.example

import spock.lang.Specification

class CalculatorTest extends Specification {
    def "Addition Test"() {
        setup:
        def lib = new Calculator()

        when:
        def result = lib.addition(2, 3)

        then:
        result == 5
    }

    def "Subtraction Test"() {
        setup:
        def lib = new Calculator()

        when:
        def result = lib.subtraction(5, 2)

        then:
        result == 3
    }

    def "Multiplication Test"() {
        setup:
        def lib = new Calculator()

        when:
        def result = lib.multiplication(4, 3)

        then:
        result == 12
    }

    def "Division Test"() {
        setup:
        def lib = new Calculator()

        when:
        def result = lib.division(10, 3)

        then:
        result == 3
    }

    def "Modulus Test"() {
        setup:
        def lib = new Calculator()

        when:
        def result = lib.modulus(10, 3)

        then:
        result == 1
    }
}
